CREATE TABLE [dbo].[ccUsers](	  [User_id] SMALLINT NOT NULL IDENTITY(1,1)	, [Login] VARCHAR(40) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [Nombres] VARCHAR(45) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [ApellidoPaterno] VARCHAR(35) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL DEFAULT('')	, [ApellidoMaterno] VARCHAR(35) COLLATE SQL_Latin1_General_CP1_CI_AS NULL DEFAULT('')	, [TipoStatusAge_id] TINYINT NOT NULL DEFAULT((0))	, [Password] VARCHAR(33) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL DEFAULT((1234))	, [TipoUser_id] INT NOT NULL DEFAULT((1))	, [Status] TINYINT NOT NULL DEFAULT((1))	, [TipoLLamadas] TINYINT NOT NULL DEFAULT((3))	, [Sexo] BIT NOT NULL DEFAULT((0))	, [filter] BIT NOT NULL DEFAULT((1))	, [CanChangeStatus] BIT NOT NULL DEFAULT((0))	, [fCreate] SMALLDATETIME NOT NULL DEFAULT(getdate())	, [DialMask] TINYINT NOT NULL DEFAULT((0))	, [XferMask] TINYINT NOT NULL DEFAULT((0))	, [LastPasswordChange] SMALLDATETIME NULL DEFAULT(getdate())	, [IDArea] SMALLINT NULL	, [NotReadyRestricted] TINYINT NOT NULL DEFAULT((0))	, [XferAgents] TINYINT NULL DEFAULT((0))	, [viewAgents] INT NULL DEFAULT((1))	, [onLine] BIT NULL DEFAULT((0))	, [startStopRecording] BIT NULL	, [LoginAttempts] INT NULL DEFAULT((0))	, [LastLoginAttempt] DATETIME NULL DEFAULT(getdate())	, [theme] SMALLINT NULL DEFAULT((0))	, [AllowChangeDialingMode] BIT NOT NULL DEFAULT((0))	, [DialingMode] TINYINT NOT NULL DEFAULT((0))	, CONSTRAINT [PK_ccUsers] PRIMARY KEY ([User_id] ASC))CREATE NONCLUSTERED INDEX [IX_ccusers] ON [dbo].[ccUsers] ([TipoStatusAge_id] ASC)CREATE NONCLUSTERED INDEX [IX_ccusers_1] ON [dbo].[ccUsers] ([TipoUser_id] ASC, [IDArea] ASC)